import pty, os, subprocess, select, time

def run_mixed(stdout_tty, stderr_tty):
    # stdout_tty/stderr_tty: True means pty, False means pipe
    if stdout_tty:
        out_master, out_slave = pty.openpty()
    else:
        out_master, out_slave = None, subprocess.PIPE
    if stderr_tty:
        err_master, err_slave = pty.openpty()
    else:
        err_master, err_slave = None, subprocess.PIPE

    # For simplicity, use Popen with stdout/stderr as slave fds or PIPE
    import subprocess
    stdout_arg = out_slave if stdout_tty else subprocess.PIPE
    stderr_arg = err_slave if stderr_tty else subprocess.PIPE
    p = subprocess.Popen(["./executable", "GET", "http://127.0.0.1:8766/json"], stdout=stdout_arg, stderr=stderr_arg, stdin=subprocess.DEVNULL)
    if stdout_tty:
        os.close(out_slave)
    if stderr_tty:
        os.close(err_slave)
    # collect
    out_data=b""
    err_data=b""
    # Use select to read from masters and pipes
    # For pipes, we need p.stdout/p.stderr
    import select
    fds = []
    fd_to_name = {}
    if stdout_tty:
        fds.append(out_master)
        fd_to_name[out_master]="out_pty"
    else:
        # p.stdout is file object
        pass
    if stderr_tty:
        fds.append(err_master)
        fd_to_name[err_master]="err_pty"

    # For pipe case, we'll just communicate at end, but for pty we need to read incrementally
    # Simplify: if both are pipes, just communicate
    if not stdout_tty and not stderr_tty:
        out,err = p.communicate()
        return out,err
    # Otherwise, read ptys, and for pipes, read via p.stdout/p.stderr with select?
    # We'll set nonblocking
    if not stdout_tty:
        os.set_blocking(p.stdout.fileno(), False)
        fds.append(p.stdout.fileno())
        fd_to_name[p.stdout.fileno()]="out_pipe"
    if not stderr_tty:
        os.set_blocking(p.stderr.fileno(), False)
        fds.append(p.stderr.fileno())
        fd_to_name[p.stderr.fileno()]="err_pipe"

    # Map fd to file descriptor for reading
    fd_map = {}
    if stdout_tty:
        fd_map[out_master]=out_master
    else:
        fd_map[p.stdout.fileno()]=p.stdout.fileno()
    if stderr_tty:
        fd_map[err_master]=err_master
    else:
        fd_map[p.stderr.fileno()]=p.stderr.fileno()

    start=time.time()
    while p.poll() is None or fds:
        r,_,_ = select.select(fds, [], [], 0.2)
        for fd in r:
            try:
                data=os.read(fd, 4096)
                if not data:
                    fds.remove(fd)
                    continue
                name=fd_to_name[fd]
                if name.startswith("out"):
                    out_data+=data
                else:
                    err_data+=data
            except:
                if fd in fds: fds.remove(fd)
        if p.poll() is not None and time.time()-start>1:
            # try drain
            for fd in list(fds):
                try:
                    import fcntl
                    while True:
                        r,_,_ = select.select([fd], [], [], 0.1)
                        if not r: break
                        data=os.read(fd,4096)
                        if not data: break
                        name=fd_to_name[fd]
                        if name.startswith("out"): out_data+=data
                        else: err_data+=data
                except: pass
            break
        if time.time()-start>5: break
    if stdout_tty: os.close(out_master)
    if stderr_tty: os.close(err_master)
    p.wait()
    return out_data, err_data

for out_tty, err_tty in [(True,True),(True,False),(False,True),(False,False)]:
    out,err = run_mixed(out_tty, err_tty)
    print(f"out_tty={out_tty} err_tty={err_tty}")
    print(f"  OUT len={len(out)} starts:{out[:100]!r}")
    print(f"  ERR len={len(err)} starts:{err[:100]!r}")
    # check if pretty (contains ESC)
    print(f"  OUT pretty? {b chr(27) in out if False else (b'\\x1b' in repr(out).encode())} has_esc={b'\\x1b' in out or b'\\033' in out or b'\\x1b' in out}")
    print(f"  OUT has ESC? {b'\\x1b' in out} {b chr(27) in out}")
    print(f"  ERR has ESC? {b chr(27) in err}")
    print()
PY"}

