func hasValidScheme(s string) bool {
	idx := strings.Index(s, "://")
	if idx == -1 {
		return false
	}
	scheme := s[:idx]
	if len(scheme) == 0 {
		return false
	}
	// First char must be letter
	c0 := scheme[0]
	if !((c0 >= 'a' && c0 <= 'z') || (c0 >= 'A' && c0 <= 'Z')) {
		return false
	}
	for i := 1; i < len(scheme); i++ {
		c := scheme[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.') {
			return false
		}
	}
	return true
}

func parseItem(s string) (typ, k, v string) {
	// Find earliest operator among ==, :=, =, :
	// Returns typ: query, jsonRaw, jsonStr, header, extra
	idxDoubleEq := strings.Index(s, "==")
	idxColonEq := strings.Index(s, ":=")
	idxEq := strings.Index(s, "=")
	idxColon := strings.Index(s, ":")
	// Determine earliest, with tie-breaker: == over = at same pos, := over : at same pos
	// Collect candidates with index != -1
	type cand struct {
		idx int
		typ string
		opLen int
	}
	var cands []cand
	if idxDoubleEq != -1 {
		cands = append(cands, cand{idxDoubleEq, "query", 2})
	}
	if idxColonEq != -1 {
		cands = append(cands, cand{idxColonEq, "jsonRaw", 2})
	}
	if idxEq != -1 {
		// But if idxEq is part of == or := at same pos, need to handle tie? Actually idxEq will be same as idxDoubleEq when s contains == at pos p (since == contains = at p). Similarly idxEq == idxColonEq+1? No, := contains = at pos+1, not same. For := at p, = at p+1, so different. For == at p, = at p (same). So for == case, both query and jsonStr candidates at same idx. Need to prefer query.
		// Similarly, idxColon will be same as idxColonEq when := at p (since := contains : at p). Need to prefer jsonRaw over header.
		// So when building cands, we have both, and later choose smallest idx, with preference for longer op (2 vs 1) when tie.
		cands = append(cands, cand{idxEq, "jsonStr", 1})
	}
	if idxColon != -1 {
		cands = append(cands, cand{idxColon, "header", 1})
	}
	if len(cands) == 0 {
		return "extra", "", s
	}
	// Find minimal idx, with tie-breaker preferring opLen 2 over 1
	sort.Slice(cands, func(i, j int) bool {
		if cands[i].idx != cands[j].idx {
			return cands[i].idx < cands[j].idx
		}
		return cands[i].opLen > cands[j].opLen
	})
	best := cands[0]
	switch best.typ {
	case "query":
		k = s[:best.idx]
		v = s[best.idx+2:]
		return "query", k, v
	case "jsonRaw":
		k = s[:best.idx]
		v = s[best.idx+2:]
		return "jsonRaw", k, v
	case "jsonStr":
		// Need to ensure this = is not part of ==? But if == exists at same idx, query would have been chosen (longer). If == exists at later idx, then this = at earlier idx wins (as observed a=b==c => data, not query). Good.
		// Similarly, if := exists, but = at earlier idx wins? e.g., a=b:=c? = at 1, := at 3? Actually a=b:=c: = at 1, := at 3? No, := at 3? Let's see: a(0) =(1) b(2) :(3) =(4) c(5). := at 3 (":="), = at 1 and 4. Earliest is = at 1, so data. Good.
		k = s[:best.idx]
		v = s[best.idx+1:]
		return "jsonStr", k, v
	case "header":
		// Similarly, if := at same idx, jsonRaw would win. Good.
		// For header, k/v not used (verbatim), but return for detection? Actually for header, we use whole s verbatim, but k is before :, v after? Not needed.
		k = s[:best.idx]
		v = s[best.idx+1:]
		return "header", k, v
	}
	return "extra", "", s
}

// For --curl quoting
func shellQuote(arg string) string {
	if strings.Contains(arg, " ") {
		// Wrap in "...", escape \, ", '
		var b strings.Builder
		b.WriteString("\"")
		for _, r := range arg {
			if r == '\\' || r == '"' || r == '\'' {
				b.WriteString("\\")
			}
			b.WriteRune(r)
		}
		b.WriteString("\"")
		return b.String()
	} else {
		// No space, escape ' only? As observed, ' escaped as \' even without space, " and \ not.
		if strings.Contains(arg, "'") {
			return strings.ReplaceAll(arg, "'", "\\'")
		}
		return arg
	}
}

